package com.gwsheridan.worldarchitect.testing;

import com.gwsheridan.worldarchitect.structure.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;

final class IslandAssetsAcceptance {
    static void check(MinecraftServer server)throws Exception{
        var registries=server.registryAccess();var cells=new ArrayList<IslandBuild.Cell>();for(int x=0;x<64;x++)for(int z=0;z<64;z++)cells.add(new IslandBuild.Cell(new BlockPos(x,0,z),Blocks.STONE.defaultBlockState(),Optional.empty()));
        cells.add(new IslandBuild.Cell(new BlockPos(2,1,2),Blocks.SAND.defaultBlockState(),Optional.empty()));cells.add(new IslandBuild.Cell(new BlockPos(3,1,3),Blocks.OAK_SLAB.defaultBlockState().setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.WATERLOGGED,true),Optional.empty()));cells.add(new IslandBuild.Cell(new BlockPos(4,1,4),Blocks.BARREL.defaultBlockState(),Optional.empty()));
        var build=new IslandBuild(new BlockPos(64,64,64),Map.of("edge",new BlockPos(63,1,63)),"edge",cells).checked(registries);var items=new ArrayList<ItemStack>(Collections.nCopies(27,ItemStack.EMPTY));items.set(26,new ItemStack(Items.OAK_SAPLING,3));build=IslandAssets.inventory(build,new BlockPos(4,1,4),items,registries);
        var original=build;var transformed=build;for(int i=0;i<4;i++)transformed=IslandAssets.transform(transformed,Rotation.CLOCKWISE_90,Mirror.NONE,registries);require(original.equals(transformed),"Four rotations changed island states, contents or markers");
        var dir=server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("island-asset-fixture");Files.createDirectories(dir);
        var path=IslandAssets.save(dir,"edge","1",build,registries);require(IslandAssets.read(path,true,registries).equals(build),"Saved island asset did not round-trip");var before=Files.readAllBytes(path);denied(()->IslandAssets.save(dir,"edge","1",original,registries));require(Arrays.equals(before,Files.readAllBytes(path)),"Duplicate save overwrote immutable asset");
        var root=new NativeTemplate(build.size(),build.cells().stream().map(c->new NativeTemplate.Cell(c.pos(),c.state(),c.data().orElse(null))).toList()).toTag();root.putInt("DataVersion",net.minecraft.SharedConstants.getCurrentVersion().dataVersion().version());var nbt=dir.resolve("edge.nbt");NbtIo.writeCompressed(root,nbt);var imported=IslandAssets.read(nbt,true,registries);require(imported.cells().equals(build.cells())&&imported.size().equals(build.size()),"64-block native import changed occupied cells");denied(()->NativeTemplate.read(root));
        var withEntities=root.copy();var entities=new ListTag();entities.add(new CompoundTag());withEntities.put("entities",entities);NbtIo.writeCompressed(withEntities,dir.resolve("entities.nbt"));denied(()->IslandAssets.read(dir.resolve("entities.nbt"),true,registries));
        var schematic=new CompoundTag();schematic.putInt("Version",3);schematic.putInt("DataVersion",net.minecraft.SharedConstants.getCurrentVersion().dataVersion().version());schematic.putShort("Width",(short)64);schematic.putShort("Height",(short)64);schematic.putShort("Length",(short)64);var palette=new CompoundTag();palette.putInt("minecraft:air",0);palette.putInt("minecraft:stone",1);var encodedBlocks=new CompoundTag();encodedBlocks.put("Palette",palette);byte[] indices=new byte[64*64*64];Arrays.fill(indices,0,4096,(byte)1);encodedBlocks.putByteArray("Data",indices);schematic.put("Blocks",encodedBlocks);var sponge=new CompoundTag();sponge.put("Schematic",schematic);var schem=dir.resolve("edge.schem");NbtIo.writeCompressed(sponge,schem);var converted=IslandAssets.read(schem,false,registries);require(converted.size().equals(new BlockPos(64,64,64))&&converted.cells().size()==4096,"Full-volume 64-block schematic lost its occupied-cell budget");
        var catalog=new com.gwsheridan.worldarchitect.config.IslandCatalog(List.of(new com.gwsheridan.worldarchitect.config.IslandCatalog.Entry("edge","Edge","","minecraft:stone",1,original)),"edge","fixed",false,64,128,0);var shifted=catalog.layout(18,512,0);require(shifted.origin(0).equals(new BlockPos(512,64,0))&&shifted.slotAt(512,0)==0&&shifted.slotAt(0,0)==-1,"Native arena island offset changed catalog addressing");
        var bad=new ArrayList<>(cells);bad.add(new IslandBuild.Cell(new BlockPos(5,1,5),Blocks.FURNACE.defaultBlockState(),Optional.empty()));var unsupported=new IslandBuild(build.size(),build.markers(),build.spawnMarker(),bad);denied(()->unsupported.checked(registries));bad.removeLast();bad.add(new IslandBuild.Cell(new BlockPos(5,2,5),Blocks.SAND.defaultBlockState(),Optional.empty()));var floating=new IslandBuild(build.size(),build.markers(),build.spawnMarker(),bad);denied(()->floating.checked(registries));
        var level=server.overworld();var origin=new BlockPos(120000,200,120000);for(int x=0;x<4;x++)for(int z=0;z<4;z++)level.getChunk((origin.getX()>>4)+x,(origin.getZ()>>4)+z);for(var c:build.cells()){var p=origin.offset(c.pos());level.setBlock(p,c.state(),18);if(c.data().isPresent()){var entity=level.getBlockEntity(p);entity.loadWithComponents(net.minecraft.world.level.storage.TagValueInput.create(net.minecraft.util.ProblemReporter.DISCARDING,registries,c.data().orElseThrow()));entity.setChanged();}}
        var captured=IslandAssets.capture(level,origin,origin.offset(63,63,63),true);require(captured.cells().size()==build.cells().size(),"64-block capture count differs: "+captured.cells().size()+" / "+build.cells().size());var barrel=captured.cells().stream().filter(c->c.pos().equals(new BlockPos(4,1,4))).findFirst().orElseThrow();require(!barrel.data().orElseThrow().getListOrEmpty("Items").isEmpty(),"Explicit capture lost starter inventory");var empty=IslandAssets.capture(level,origin,origin.offset(63,63,63),false);require(empty.cells().stream().allMatch(c->c.data().map(t->t.getListOrEmpty("Items").isEmpty()).orElse(true)),"Excluded capture copied inventories");
        require(java.util.concurrent.CompletableFuture.supplyAsync(()->{try{IslandAssets.capture(level,origin,origin.offset(63,63,63),false);return false;}catch(IllegalStateException expected){return true;}catch(Exception e){throw new IllegalStateException(e);}}).join(),"Worker-thread capture was accepted");
        System.out.println("WA18_ISLAND_ASSETS_PASS bounds=64 occupied="+build.cells().size()+" inventory_slot=26 rotations=4 immutable=true rejected=entities,machine,unsupported_gravity,worker");
    }
    @FunctionalInterface private interface Action{void run()throws Exception;}
    private static void denied(Action action)throws Exception{try{action.run();throw new AssertionError("Expected island asset rejection");}catch(java.io.IOException|IllegalArgumentException expected){}}
    private static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
}
